/*
# Expand error codes reference (add codes to all categories)

1. What this does
- Adds new error-code rows to the existing `error_codes` table for every appliance
  category used by the app. Existing 20 rows are NOT touched.
- Each new row carries: category, code, short description, probable cause, and
  recommended solution — the same shape the app already renders.

2. Tables modified
- `error_codes` — INSERT only. No columns added, no types changed, no data deleted.

3. Idempotency
- Uses a uniqueness guard on (category, code): the INSERT only runs for rows that
  do not already exist, so re-running the migration never duplicates entries.

4. Security
- No changes. RLS and existing policies on `error_codes` remain as-is.
*/

INSERT INTO error_codes (category, code, description, cause, solution)
SELECT v.category, v.code, v.description, v.cause, v.solution
FROM (VALUES
  -- Стиральные машины
  ('СТИРАЛЬНЫЕ МАШИНЫ','E06','Не набирает воду','Закрыт кран подачи, забит заливной клапан или неисправен датчик уровня','Проверить кран и шланг, прочистить/заменить заливной клапан, при необходимости заменить прессостат'),
  ('СТИРАЛЬНЫЕ МАШИНЫ','E07','Не отжимает бельё','Изношены щётки двигателя, неисправен таходатчик или сбой модуля управления','Проверить щётки и таходатчик, перезапустить программу, при повторении — диагностика модуля'),
  ('СТИРАЛЬНЫЕ МАШИНЫ','E08','Сильная вибрация и шум','Износ подшипников барабана, ослаблен противовес или остались транспортировочные болты','Снять транспортировочные болты, подтянуть противовес; при износе — замена подшипникового узла'),
  ('ПОСУДОМОЕЧНЫЕ МАШИНЫ','E13','Не сливает воду','Засор сливного фильтра, помпы или шланга','Прочистить фильтр и сливной тракт, проверить крыльчатку помпы, заменить помпу при неисправности'),
  ('ПОСУДОМОЕЧНЫЕ МАШИНЫ','E14','Не сушит посуду','Неисправен ТЭН сушки или вентилятор, сработал термопредохранитель','Проверить ТЭН, вентилятор и предохранитель тестером, заменить неисправный элемент'),
  ('ХОЛОДИЛЬНИКИ','E52','Плохо холодит, намерзает лёд','Утечка хладагента, забит капиллярный трубопровод или неисправен датчик испарителя','Найти и устранить утечку, заправить хладагент; проверить и при необходимости заменить датчик'),
  ('ХОЛОДИЛЬНИКИ','E53','Не работает свет в камере','Перегорела лампа, неисправен выключатель или повреждена проводка','Заменить лампу, проверить кнопку-выключатель двери и целостность проводки'),
  ('ХОЛОДИЛЬНИКИ','E54','Появляется вода под ящиками','Засор дренажного отверстия системы оттайки','Прочистить дренажное отверстие и трубку тёплой водой, проверить поддон для конденсата'),
  ('ТЕЛЕВИЗОРЫ','E23','Нет приёма каналов','Сбой настройки, неисправен тюнер или повреждена антенна','Пересканировать каналы, проверить кабель и антенну, при неисправности заменить тюнер'),
  ('ТЕЛЕВИЗОРЫ','E24','Полосы на экране','Проблема шлейфа матрицы, неисправность платы T-CON или самой матрицы','Переподключить шлейфы, заменить плату T-CON; при дефекте матрицы — замена панели'),
  ('КОМПЬЮТЕРЫ','E32','Не видит жёсткий диск','Плохой контакт SATA-кабеля, сбой диска или неисправность порта','Переподключить кабели питания и данных, проверить диск на другом ПК, заменить при сбоях'),
  ('КОМПЬЮТЕРЫ','E33','Нет звука','Не установлены драйверы, отключена звуковая карта в BIOS или неисправность аудиочипа','Проверить драйверы и настройки BIOS, переустановить аудиодрайвер; при неисправности чипа — ремонт платы'),
  ('НОУТБУКИ','E42','Перегрев и выключение','Забит радиатор пылью, высохла термопаста, изношен кулер','Чистка системы охлаждения, замена термопасты, замена кулера при шуме или остановке'),
  ('НОУТБУКИ','E43','Не работает клавиатура','Залит шлейф клавиатуры, износ мембраны или сбой контроллера','Проверить шлейф, просушить плату после залития, заменить клавиатуру'),
  ('ВОДОНАГРЕВАТЕЛИ','E61','Срабатывает защита, выбивает автомат','Пробой ТЭНа на корпус, утечка тока или неисправность УЗО','Проверить ТЭН мегомметром, заменить при пробое; проверить УЗО и заземление'),
  ('ВОДОНАГРЕВАТЕЛИ','E62','Течёт вода из бака','Коррозия бака, износ прокладки фланца или течь по подводке','Затянуть и перепаковать фланец с новой прокладкой; при коррозии бака — замена бака'),
  ('ДУХОВЫЕ ШКАФЫ','E71','Не работает гриль','Перегорел гриль-ТЭН или неисправен переключатель режимов','Прозвонить ТЭН, заменить при обрыве; проверить и заменить переключатель'),
  ('ДУХОВЫЕ ШКАФЫ','E72','Не работает подсветка/таймер','Перегорела лампа, сбой платы таймера или плохой контакт','Заменить лампу, проверить контакты; при сбое таймера — ремонт или замена платы'),
  ('ВАРОЧНЫЕ ПАНЕЛИ','E81','Конфорка греет слабо','Частичный обрыв спирали ТЭНа, окислены клеммы или сбой сенсора мощности','Прозвонить спираль, зачистить клеммы; при обрыве — замена конфорки'),
  ('ВАРОЧНЫЕ ПАНЕЛИ','E82','Панель не реагирует на касания','Влага или жир на сенсорах, сбой сенсорного модуля','Обесточить панель на 10 минут, обезжирить поверхность; при повторении — замена сенсорного блока')
) AS v(category, code, description, cause, solution)
WHERE NOT EXISTS (
  SELECT 1 FROM error_codes e
  WHERE e.category = v.category AND e.code = v.code
);